sys_script_include.script:
var MSS_Treasury_Client_Utils = Class.create();
MSS_Treasury_Client_Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    updateAssignToNullForClient: function() {
        const taskSysID = this.getParameter("sysparm_task_sys_id");
        if (!taskSysID) {
            this.errorLogAndXmatterAlert("WARNING", '[iQube - Treasury]: MSS_Treasury_Client_Utils.updateAssignToNullForClient | Task Sys ID is empty!');
            return "false";
        }
        const taskGR = new GlideRecordSecure("x_hsb11_mss_tsd_treasury_case_task");
        if (!taskGR.get(taskSysID)) {
            const errorMessage = '[iQube - Treasury]: MSS_Treasury_Client_Utils.updateAssignToNullForClient | Task Not Found! Sys ID is ' + taskSysID;
            this.errorLogAndXmatterAlert("WARNING", errorMessage);
            return "false";
        }
        taskGR.assigned_to = "";
        taskGR.update();
        return "true";
    },
    /**
     * @param {'CRITICAL'|'MAJOR'|'MINOR'|'WARNING'|'INFO'} severity
     * @param {string} txt
     */
    xMatterAlert(severity, txt) {
        try {
            new x_hsb11_mss_tsd.MSS_Treasury_XMatter_ITID_WidgetFailureHandler().createITIDEvent(severity, txt, 'MSS-OT-IQUBE-SERVICENOW-TREASURY');
        } catch (errorInfo) {
            gs.error('[iQube - Treasury]: MSS_Treasury_Client_Utils.xMatterAlert | Unknown exception while processing' + errorInfo.message);
        }
    },

    errorLogAndXmatterAlert(severity, message) {
        const logPrefix = "[iQube - Treasury]: MSS_Treasury_Client_Utils: ";
        const finalMessage = logPrefix + message;
        gs.error(finalMessage);
        this.xMatterAlert(severity, finalMessage);
    },

    type: "MSS_Treasury_Client_Utils",
});
